<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Jobs\Dezerx\ApplyServerVersion; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\VersionCatalog; use Pterodactyl\Services\Dezerx\Minecraft\InstalledVersion; use Pterodactyl\Services\Dezerx\Minecraft\LaunchConfigurator; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\VersionApplyRequest; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class VersionController extends ClientApiController { public function index(AddonRequest $request, Server $server): JsonResponse { $platforms = []; foreach (VersionCatalog::platforms() as $id => $meta) { $platforms[] = [ 'id' => $id, 'label' => $meta['label'], 'icon' => $meta['icon'], 'color' => $meta['color'], 'description' => $meta['description'], 'group' => $meta['group'], 'groupLabel' => $meta['groupLabel'], 'experimental' => $meta['experimental'], 'deprecated' => $meta['deprecated'], 'versionCount' => $meta['versionCount'], 'builds' => $meta['builds'], ]; } return new JsonResponse(['platforms' => $platforms]); } public function installed(AddonRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $current = InstalledVersion::read($files); if ($current !== null && $current['label'] === null && $current['platform'] !== null) { $current['label'] = VersionCatalog::platforms()[$current['platform']]['label'] ?? null; } return new JsonResponse([ 'installed' => $current, 'launch' => [ 'argfile' => app(LaunchConfigurator::class)->argfile($files), 'jar' => $this->jarName($server), 'image' => $this->imageLabel($server), ], ]); } public function versions(AddonRequest $request, Server $server, string $platform): JsonResponse { $this->assertSupported($platform); return new JsonResponse(['versions' => VersionCatalog::versions($platform)]); } public function builds(AddonRequest $request, Server $server, string $platform): JsonResponse { $this->assertSupported($platform); $version = (string) $request->query('version', ''); return new JsonResponse([ 'builds' => $this->known($platform, $version) ? VersionCatalog::builds($platform, $version) : [], ]); } public function apply(VersionApplyRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'platform' => ['required', 'string'], 'version' => ['required', 'string'], 'build' => ['nullable', 'string'], 'wipe' => ['sometimes', 'boolean'], 'eula' => ['sometimes', 'boolean'], ]); $platform = (string) $data['platform']; $version = (string) $data['version']; $this->assertSupported($platform); if (!$this->known($platform, $version)) { return new JsonResponse([ 'errors' => [['code' => 'UnknownVersion', 'detail' => 'That version is not one this platform publishes.']], ], 422); } if (ApplyServerVersion::inFlight($server->uuid)) { return new JsonResponse([ 'errors' => [['code' => 'AlreadyRunning', 'detail' => 'A version change is already running.']], ], 409); } ApplyServerVersion::mark($server->uuid, 'queued', 'Waiting for a free worker.'); $wipe = (bool) ($data['wipe'] ?? false); ApplyServerVersion::dispatch( $server, $platform, $version, $data['build'] ?? null, $this->jarName($server), $wipe, (bool) ($data['eula'] ?? false), ); Activity::event('server:version.apply') ->property(['platform' => $platform, 'version' => $version, 'wipe' => $wipe]) ->log(); return new JsonResponse([ 'started' => true, 'message' => 'Stopping the server and applying that version.', ], 202); } public function status(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse(ApplyServerVersion::status($server->uuid)); } private function jarName(Server $server): string { foreach ($server->variables as $variable) { if ($variable->env_variable !== 'SERVER_JARFILE') { continue; } $name = trim((string) ($variable->server_value ?? $variable->default_value ?? '')); if ($name !== '' && !str_contains($name, '/') && !str_contains($name, '..')) { return $name; } } return 'server.jar'; } private function imageLabel(Server $server): ?string { foreach ((array) $server->egg->docker_images as $label => $image) { if ($image === $server->image) { return (string) $label; } } return null; } private function known(string $platform, string $version): bool { foreach (VersionCatalog::versions($platform) as $entry) { if (($entry['id'] ?? null) === $version) { return true; } } return false; } private function assertSupported(string $platform): void { if (!VersionCatalog::supports($platform)) { throw new NotFoundHttpException(); } } } 